const rows = $input.all().map(i => i.json).filter(r => r && r.id != null);
const dateStr = new Date().toLocaleDateString('sk-SK', { timeZone: 'Europe/Bratislava' });

const FLOWS = {
  Today_pdr: 'New notification (Today_pdr)',
  Reminders_pdr: 'Reminder (Reminders_pdr)',
  Aggressive_mode: 'Aggressive (Aggressive_mode)',
};

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmtTime = (v) => {
  if (!v) return '';
  const d = new Date(v);
  return isNaN(d.getTime()) ? '' : d.toLocaleTimeString('sk-SK', { timeZone: 'Europe/Bratislava', hour: '2-digit', minute: '2-digit' });
};

const counts = { Today_pdr: 0, Reminders_pdr: 0, Aggressive_mode: 0 };
for (const r of rows) { if (counts[r.flow] !== undefined) counts[r.flow]++; }
const total = rows.length;

let subject, html;

if (total === 0) {
  subject = `FLEETSYNC digest ${dateStr} — nothing to send today`;
  html = `<p><b>FLEETSYNC digest — ${dateStr}</b></p>`
       + `<p>Nothing was sent today by any flow (Today_pdr, Reminders_pdr, Aggressive_mode).</p>`;
} else {
  const summaryBits = Object.keys(FLOWS)
    .filter((k) => counts[k] > 0)
    .map((k) => `${counts[k]} ${k.replace('_pdr', '').replace('_mode', '').toLowerCase()}`);
  subject = `FLEETSYNC digest ${dateStr} — ${total} sent (${summaryBits.join(', ')})`;

  const head = ['Flow', 'Recipient', 'Name', 'Vehicle', 'Type', 'Channel', 'Status', 'Attempt / Day', 'Time'];
  const thead = `<tr>${head.map((h) => `<th style="text-align:left;padding:5px 9px;border-bottom:2px solid #bbb;">${h}</th>`).join('')}</tr>`;
  const trows = rows.map((r) => {
    const attemptDay = r.flow === 'Aggressive_mode'
      ? (r.aggressive_days_sent != null ? `day ${r.aggressive_days_sent}/30` : '')
      : r.flow === 'Reminders_pdr'
        ? (r.confirmationAttempts != null ? `attempt ${r.confirmationAttempts}/3` : '')
        : '';
    const cells = [
      FLOWS[r.flow] || r.flow || '',
      r.email, r.personName, r.vehicleRegistration, r.notificationType,
      r.notificationChannel, r.status, attemptDay, fmtTime(r.sent_at),
    ];
    return `<tr>${cells.map((c) => `<td style="padding:5px 9px;border-bottom:1px solid #eee;">${esc(c)}</td>`).join('')}</tr>`;
  }).join('');
  const perFlow = Object.keys(FLOWS).map((k) => `${FLOWS[k]}: <b>${counts[k]}</b>`).join(' &nbsp;|&nbsp; ');
  html = `<p><b>FLEETSYNC digest — ${dateStr}</b></p>`
       + `<p>Total emailed / notified today: <b>${total}</b><br>${perFlow}</p>`
       + `<table style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:13px;">${thead}${trows}</table>`;
}

return [{ json: { subject, html, total } }];

